var GRP_PROPS = [{"q": "ترکیبِ هر دو عضو، خودش عضوِ همان مجموعه است", "nick": "بسته بودن", "have": [1, 1, 1, 1], "why": "دو عددِ درست را جمع کن، بازهم عددِ درست است. دو کسرِ ناصفر را ضرب کن، بازهم کسرِ ناصفر. دو چرخش پشتِ سر هم، بازهم یکی از همان چهار چرخش. هیچ‌کدام از مجموعه بیرون نمی‌زنند."}, {"q": "یک عضوِ بی‌اثر وجود دارد", "nick": "عضوِ همانی", "have": [1, 1, 1, 1], "why": "در جمع، صفر. در ضرب، یک. در چرخش، چرخشِ صفر درجه. در جابه‌جایی، «هیچ‌کاری نکن». هر چهار دستگاه چنین عضوی دارند — و توجه کن که در هر کدام چیزِ متفاوتی است."}, {"q": "هر عضو یک عضوِ خنثاکننده دارد", "nick": "وارون", "have": [1, 1, 1, 1], "why": "وارونِ ۵ در جمع، −۵ است. وارونِ ۲⁄۳ در ضرب، ۳⁄۲. وارونِ چرخشِ ۹۰ درجه، چرخشِ ۲۷۰ درجه. وارونِ یک جابه‌جایی، برگرداندنش. هر چهار تا این را دارند — و همین است که «تفریق» و «تقسیم» را بی‌نیاز می‌کند."}, {"q": "جای پرانتزها مهم نیست", "nick": "شرکت‌پذیری", "have": [1, 1, 1, 1], "why": "(۲+۳)+۴ همان ۲+(۳+۴) است. برای ترکیبِ چرخش‌ها هم همین‌طور. این خاصیت آن‌قدر بدیهی به نظر می‌رسد که کسی اسمش را نمی‌پرسد — تا اینکه در اوکتونیون‌ها از دست می‌رود و معلوم می‌شود مجانی نبوده."}, {"q": "ترتیبِ دو عضو مهم نیست", "nick": "جابه‌جایی", "have": [1, 1, 1, 0], "why": "۲+۳ همان ۳+۲ است و چرخش‌ها هم با هم جابه‌جا می‌شوند. ولی جابه‌جاییِ سه مهره نه: «اول اولی و دومی را عوض کن، بعد دومی و سومی» با ترتیبِ برعکس به دو نتیجهٔ مختلف می‌رسد. این خاصیت «مشترک نیست» — و همین باعث می‌شود از تعریف بیرون بماند."}, {"q": "تعدادِ اعضا متناهی است", "nick": "متناهی بودن", "have": [0, 0, 1, 1], "why": "عددهای درست بی‌شمارند، کسرها هم. ولی چرخش‌های مربع فقط چهار تا و جابه‌جایی‌های سه مهره شش تا. مشترک نیست، پس به تعریف راه ندارد."}, {"q": "می‌شود اعضا را از کوچک به بزرگ مرتب کرد، سازگار با عمل", "nick": "ترتیب", "have": [1, 0, 0, 0], "why": "عددهای درست ترتیب دارند. ولی «چرخشِ ۹۰ درجه از چرخشِ ۱۸۰ درجه کوچک‌تر است» هیچ معنایی ندارد. مشترک نیست."}];
